highlights={
 'szn-1':['D0326','D0331','D0366'],
 'szn-2':['L0119','L0089','L0010','L0717'],
 'szn-3':['D1558','D1864','D1601'],
 'szn-4':['L1574','L1501','L1156','L1184','L1048'],
 'szn-5':['P0173','P0227','P0190','P0218'],
 'szn-6':['D2876','D2908','D2887','D2929'],
 'division-0':['D3078','D3094','D3113','D3097'],
 'wa-final-esp-arg':['D3207','D3143','D3238'],
 'wa-semi-eng-arg':['D3567','D3414','D3487'],
 'wa-semi-esp-fra':['D3607','D3580','D3604'],
 'wa-norway-england':['D3629','D3640','D3732'],
 'wa-ucl-final-night':['L2080','L2125','L2189'],
 'frontier-futsal':['P0090','P0078','P0096','P0043'],
 'turf-wars':['L1979','L1978']}
selected=sorted({k for r in rows for k in [r['best'],r['backup']]}|{k for v in highlights.values() for k in v})
photo_data={}
for key in selected:
    x=items[key];preview=ROOT/'full-previews'/f'{key}.jpg'
    if not preview.exists():
        with Image.open(x['path']) as im:ImageOps.contain(ImageOps.exif_transpose(im).convert('RGB'),(1800,1800)).save(preview,quality=96)
    # Portable HTML embeds a review-sized copy once per unique photograph.
    with Image.open(preview) as im:
        import io
        b=io.BytesIO();ImageOps.contain(im,(1100,1100)).save(b,format='JPEG',quality=90)
    src='data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
    local_original=''
    if key.startswith('L'):
        dest=ROOT/'originals'/f"{key}{Path(x['path']).suffix.lower()}"
        if not dest.exists():shutil.copy2(x['path'],dest)
        local_original=f'originals/{dest.name}'
    photo_data[key]=dict(key=key,name=x['name'],w=x['w'],h=x['h'],source=x.get('source') or (f"https://drive.google.com/file/d/{x['id']}/view" if x.get('id') else x['path']),local_original=local_original,path=x.get('path',''),image=src,quality=f'quality/{key}.jpg' if (ROOT/'quality'/f'{key}.jpg').exists() else '',group=x.get('group') or x.get('album',''))

summary='Home hero reserved for video: no photo recommendation or replacement there. Reviewed 4,176 Drive preview entries, 2,181 readable unique disk JPEG/PNG copies, 243 existing credited album derivatives, and 11 embedded RAW previews. Sources overlap; these counts are not unique moments. 76 disk JPEG/PNG copies failed decoding; 135 exact duplicates excluded. 13 RAW files found: two yielded no preview and one preview is visibly damaged. RAWs are organizer portraits, not better match winners. Downloaded 47 Drive originals and verified checksums; inspected 27 disk originals at full detail (74 shortlisted original checks). All 108 current image export entries were skimmed. Not every archive image was inspected at original size.'
gaps=[
 'No watch-party source inspected meets a literal grain-free, close-up full-screen bar. Use restrained cards, obtain better originals, or replace large placements with the strongest clean football photos where the story permits.',
 'SZN6 originals are mostly 2–3k pixels with softened detail; no larger version found in its Picks folder. Keep event-specific photos at medium size.',
 'Turf has unreadable and partly corrupted files. The two intact group frames are contextual picks, not pristine close-up hero images.',
 'SZN5 and Ground Zero have credited ThePapare derivatives on disk/site; source camera originals were not found. Preserve watermarks and credits. SZN5 video still is excluded from the photos-only shortlist.',
 'Team portraits cannot be forced into narrow portrait crops without removing people. Change the frame ratio or compose a separate phone layout.',
 'Formal Drive headshots have no verified person-to-role mapping. Team section currently has no live portrait slots; do not assign identities.',
 'Archive browsing can retain event coverage separately; feature only the curated highlights. This report does not certify every archive photo as pristine. Unused legacy gallery p01–p19/v01–v04 data is not a live placement in the current gallery route.',
 'Actual website replacement/export/animation checks remain a separate implementation step. This report includes crop guidance and simulations, not final retouched assets or a deployed site.'
]
payload=dict(rows=rows,photos=photo_data,highlights=highlights,summary=summary,gaps=gaps)
(ROOT/'selection.json').write_text(json.dumps({**payload,'photos':{k:{kk:vv for kk,vv in v.items() if kk!='image'} for k,v in photo_data.items()}},indent=2),encoding='utf-8')
template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Frontier • Photo shortlist</title><style>
*{box-sizing:border-box}body{margin:0;background:#101512;color:#f4f3e7;font:16px/1.55 system-ui,sans-serif}header,main{max-width:1320px;margin:auto;padding:36px 28px}header{padding-bottom:16px}h1{font-size:clamp(32px,5vw,64px);line-height:1.05;margin:12px 0}h2{font-size:24px}h3{font-size:18px;margin:12px 0 6px}p{max-width:90ch}.muted,small{color:#bdc7be}a{color:#d8ef80;overflow-wrap:anywhere}button,select{font:inherit;padding:10px 16px;border:1px solid #74836b;background:#1c261e;color:inherit;border-radius:6px;cursor:pointer}.controls{display:flex;flex-wrap:wrap;gap:10px;position:sticky;top:0;background:#101512;padding:16px 0;z-index:4}section{border-top:1px solid #52604d;padding:22px 0;margin:22px 0}article{border:1px solid #47533f;border-radius:8px;padding:18px;background:#19221b} .pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.photo{width:100%;height:300px;object-fit:contain;background:#0c100d}.badge{display:inline-block;background:#dcf181;color:#17200e;padding:3px 9px;font-size:12px;border-radius:20px}.conditional{background:#f5c57b}.assets{font-size:13px;color:#bdc7be;overflow-wrap:anywhere}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.gallery img{height:200px}.crop-demo{display:flex;gap:16px;align-items:start;flex-wrap:wrap}.wide{width:min(800px,100%);aspect-ratio:16/9;position:relative;overflow:hidden}.phone{width:220px;aspect-ratio:400/750;position:relative;overflow:hidden}.crop-demo img{width:100%;height:100%;object-fit:cover;object-position:62% center}.overlay{position:absolute;inset:0;padding:18px;background:linear-gradient(#000a,transparent 55%);font-weight:800;font-size:clamp(20px,3vw,34px);line-height:1.1}.phone .overlay{font-size:23px}li{margin-bottom:10px}.hide{display:none}@media(max-width:650px){header,main{padding:22px 16px}.pair,.gallery{grid-template-columns:1fr}.photo{height:auto;max-height:350px}.controls{position:static}.phone{width:200px}article{padding:13px}}
</style><header><span class="badge">13 OCTOBER 2026 • SELECTION REVIEW</span><h1>The strongest frames.<br>For the rest of Frontier.</h1><p><strong>The home hero is reserved for video.</strong> This shortlist starts immediately below it. Main picks, backups, source files and crop guidance are grouped by website placement.</p><p class="muted" id="summary"></p></header><main><div class="controls"><select id="filter" aria-label="Filter by website area"><option value="all">All website placements</option></select><button onclick="document.getElementById('gaps').scrollIntoView()">Quality gaps</button><button onclick="document.getElementById('albumsets').scrollIntoView()">Album highlights</button><button onclick="document.getElementById('crop').scrollIntoView()">First-section crop</button></div><div id="slots"></div><section id="crop"><h2>First section after the video</h2><p>Illustrative desktop and phone crops of the primary pick. The phone focuses on the central players and ball. These are crop simulations, not screenshots of the website’s final layout or animation.</p><div class="crop-demo"><div class="wide"><img id="desktopcrop" alt="Daylight SZN4 football crop"><div class="overlay">A platform for Sri Lanka’s<br>football community.</div></div><div class="phone"><img id="phonecrop" alt="Phone crop of central players"><div class="overlay">A platform for Sri Lanka’s football community.</div></div></div></section><section id="gaps"><h2>Where the source does not meet the bar</h2><ul id="gaplist"></ul></section><section id="albumsets"><h2>Featured album highlights</h2><p>Use these small sets for editorial features. They keep action, people and detail varied. Conditional photos carry the same size/noise limits listed above. The full archive remains event coverage, not a quality-certified featured set.</p><div id="sets"></div></section><p class="muted">Originals preserved. No website replacement, photo retouching or deployment performed.</p></main><script>const DATA=__DATA__;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.getElementById('summary').textContent=DATA.summary;
function card(key,label){const p=DATA.photos[key];return `<article><span class="badge">${label}</span><h3>${key} · ${esc(p.name)}</h3><a href="full-previews/${key}.jpg" target="_blank"><img class="photo" src="${p.image}" alt="${esc(p.name)}"></a><p>${p.w} × ${p.h} source pixels<br>${p.source.startsWith('https')?`<a href="${esc(p.source)}" target="_blank" rel="noopener">Open Drive source</a>`:`<a href="${p.local_original||'full-previews/'+key+'.jpg'}" target="_blank">Open local ${p.local_original?'original copy':'derivative'}</a><br><small>Source: ${esc(p.source)}</small>`}${p.quality?`<br><a href="${p.quality}" target="_blank">Full frame + 100% detail panel</a>`:''}</p></article>`}
document.getElementById('slots').innerHTML=DATA.rows.map((r,i)=>`<section class="slot" data-group="${esc(r.section)}"><span class="badge ${r.status.startsWith('Conditional')?'conditional':''}">${esc(r.status)}</span><h2>${i+1}. ${esc(r.slot)}</h2><p class="assets">${esc(r.assets)}</p><p>${esc(r.reason)}</p><p><strong>Framing:</strong> ${esc(r.crop)}</p><div class="pair">${card(r.best,'PRIMARY')}${card(r.backup,'BACKUP')}</div></section>`).join('');
[...new Set(DATA.rows.map(r=>r.section))].forEach(s=>document.getElementById('filter').add(new Option(s,s)));
document.getElementById('filter').onchange=e=>document.querySelectorAll('.slot').forEach(el=>el.classList.toggle('hide',e.target.value!='all'&&el.dataset.group!=e.target.value));
document.getElementById('gaplist').innerHTML=DATA.gaps.map(g=>`<li>${esc(g)}</li>`).join('');
document.getElementById('sets').innerHTML=Object.entries(DATA.highlights).map(([album,keys])=>`<section><h3>${esc(album)}</h3><div class="gallery">${keys.map(k=>card(k,'FEATURED')).join('')}</div></section>`).join('');
document.getElementById('desktopcrop').src=DATA.photos.L1542.image;document.getElementById('phonecrop').src=DATA.photos.L1542.image;
</script></html>'''
(ROOT/'shortlist.html').write_text(template.replace('__DATA__',json.dumps(payload,separators=(',',':'))),encoding='utf-8')
md=['# Frontier website photo shortlist — 2026-10-13','','Home hero: video. No photo slot or still replacement proposed.','','Open `shortlist.html` for primary/backup previews, source links, quality warnings and the first-section crop simulation.','',summary,'','## Placement map','', '| Placement | Primary | Backup | Verdict |','|---|---|---|---|']
for r in rows:md.append(f"| {r['slot']} | {r['best']} — {items[r['best']]['name']} | {r['backup']} — {items[r['backup']]['name']} | {r['status']} |")
md+=['','## Source and crop details','']
for r in rows:
    md += [f"### {r['slot']}",f"Current slots: `{r['assets']}`",'',r['reason'],f"Framing: {r['crop']}",'']
    for label,key in [('Primary',r['best']),('Backup',r['backup'])]:
        p=photo_data[key];md.append(f"- {label}: [{key} — {p['name']}]({p['source'].replace(chr(92),'/')}) · {p['w']}×{p['h']} · [preview](full-previews/{key}.jpg)")
    md.append('')
md+=['## Gaps','']+[f'- {g}' for g in gaps]+['','## Checks and limits','','All preview contact sheets skimmed. 74 shortlisted camera originals inspected through full frames and 100% detail panels. Third-party derivatives inspected locally; raw previews only, no RAW development. Crop simulations reviewed separately from the actual website. Phone and desktop website integration remains untested because no site changes were requested in this selection pass. Browser access to the local report was rejected because permission was declined; no alternate browser workaround attempted. HTML/JavaScript and source links were checked structurally; the report itself was not visually verified in a browser.']
(ROOT/'shortlist.md').write_text('\n'.join(md),encoding='utf-8')
print('Placement decisions',len(rows),'Unique photos',len(selected),'Portable HTML MB',round((ROOT/'shortlist.html').stat().st_size/1e6,2))
